def lps(s: str) -> int:
    def longest_palindromic_subsequence(s: str) -> int:
        n = len(s)
        dp = [[0] * n for _ in range(n)]

        # Every single character is a palindrome of length 1
        for i in range(n):
            dp[i][i] = 1

        # Build the table
        for cl in range(2, n + 1):  # cl is the current length of substring
            for i in range(n - cl + 1):
                j = i + cl - 1
                if s[i] == s[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        return dp[0][n - 1]

    # Remove non-alphanumeric characters and make the string uppercase for uniformity
    cleaned_s = ''.join(filter(str.isalnum, s)).upper()  # Only consider alphanumeric characters
    return longest_palindromic_subsequence(cleaned_s)
