def sum_of_digits(numbers):
    def digit_sum(num):
        if isinstance(num, int):  # Only process integers
            return sum(int(digit) for digit in str(abs(num)))  # Handle negative numbers gracefully
        return 0  # Ignore non-integer values

    # Flatten the input list to handle nested lists and calculate the digit sum
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    return sum(digit_sum(num) for num in flatten(numbers))

# Example usage and test cases:
assert sum_of_digits([10, 2, 56]) == 14
assert sum_of_digits([10, 20, 4, 5, 'b', 70, 'a']) == 19
assert sum_of_digits([1, 2, 3, 'x', [], 10]) == 7
assert sum_of_digits([]) == 0
assert sum_of_digits([123, 'abc', 45]) == 15
assert sum_of_digits([[10, 20, 4, 5, 'b', 70, 'a']]) == 19
assert sum_of_digits([[-10, 20], [4, [5, 'b'], 70], 'a']) == 19
