def max_Product(arr):
    if len(arr) < 2:
        return None  # Not enough elements for a pair

    # Initialize variables to track the two largest and two smallest numbers
    max1 = max2 = float('-inf')  # Two largest numbers
    min1 = min2 = float('inf')   # Two smallest numbers

    # Traverse the array to find the two largest and two smallest numbers
    for num in arr:
        # Update the two largest numbers
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the two smallest numbers
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Calculate the products of the two largest and two smallest numbers
    product1 = max1 * max2  # Product of two largest numbers
    product2 = min1 * min2  # Product of two smallest numbers

    # Return the pair that gives the highest product
    if product1 > product2:
        return (max2, max1)
    else:
        return (min1, min2)

# Example test cases
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([-10, -20, 3, 4, 7, 0, 8, 4]) == (-20, -10)
assert max_Product([1, 2]) == (1, 2)
assert max_Product([-1, -2, -3, -4]) == (-3, -4)
assert max_Product([0, 0, 0]) == (0, 0)
```

