def comb_sort(arr):
    def get_next_gap(gap):
        # Shrink factor is 1.3
        gap = (gap * 10) // 13
        return max(1, gap)

    n = len(arr)
    gap = n
    swapped = True

    while gap != 1 or swapped:
        gap = get_next_gap(gap)
        swapped = False

        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr
